// src/routes/calculadora-contratos.ts
var PADRAO = {
  baseSalary: 2500,
  // salário fixo
  contractsTarget: 10,
  // meta do mês, em contratos
  bonusValue: 800,
  // bônus integral (100% da meta)
  averageTicket: 2500,
  // ticket médio do contrato (só para mostrar o volume)
  commissionPerContract: 250,
  // comissão FIXA por contrato fechado, em reais
  contractsClosed: 0
  // fechados até agora
};
async function migrateCalculadoraContratos(pool) {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS calculadora_contratos_data (
      id         serial PRIMARY KEY,
      data       jsonb NOT NULL,
      updated_at timestamptz NOT NULL DEFAULT now()
    );
  `);
}
function setupCalculadoraContratosRoutes(app, pool) {
  const numero = (v, padrao) => {
    const n = parseFloat(v);
    return Number.isFinite(n) && n >= 0 ? n : padrao;
  };
  app.get("/api/calculadora-contratos", async (_req, res) => {
    try {
      const r = await pool.query(
        `SELECT data FROM calculadora_contratos_data ORDER BY updated_at DESC LIMIT 1`
      );
      const raw = r.rows[0]?.data || {};
      res.json({
        baseSalary: numero(raw.baseSalary, PADRAO.baseSalary),
        contractsTarget: numero(raw.contractsTarget, PADRAO.contractsTarget),
        bonusValue: numero(raw.bonusValue, PADRAO.bonusValue),
        averageTicket: numero(raw.averageTicket, PADRAO.averageTicket),
        commissionPerContract: numero(raw.commissionPerContract, PADRAO.commissionPerContract),
        contractsClosed: numero(raw.contractsClosed, PADRAO.contractsClosed)
      });
    } catch (err) {
      console.error("[calculadora-contratos] GET:", err.message);
      res.status(500).json({ error: "Falha ao carregar a calculadora." });
    }
  });
  app.post("/api/calculadora-contratos", async (req, res) => {
    try {
      const b = req.body || {};
      const data = {
        baseSalary: numero(b.baseSalary, PADRAO.baseSalary),
        contractsTarget: numero(b.contractsTarget, PADRAO.contractsTarget),
        bonusValue: numero(b.bonusValue, PADRAO.bonusValue),
        averageTicket: numero(b.averageTicket, PADRAO.averageTicket),
        commissionPerContract: numero(b.commissionPerContract, PADRAO.commissionPerContract),
        contractsClosed: numero(b.contractsClosed, PADRAO.contractsClosed)
      };
      const existe = await pool.query(
        `SELECT id FROM calculadora_contratos_data ORDER BY updated_at DESC LIMIT 1`
      );
      if (existe.rows[0]) {
        await pool.query(
          `UPDATE calculadora_contratos_data SET data=$1, updated_at=now() WHERE id=$2`,
          [data, existe.rows[0].id]
        );
      } else {
        await pool.query(`INSERT INTO calculadora_contratos_data (data) VALUES ($1)`, [data]);
      }
      res.json({ success: true });
    } catch (err) {
      console.error("[calculadora-contratos] POST:", err.message);
      res.status(500).json({ error: "Falha ao salvar a calculadora." });
    }
  });
}

// src/routes/zapsign.ts
var ZAPSIGN_BASE = "https://api.zapsign.com.br/api/v1";
var assinaturaDaGrape = () => {
  const email = (process.env.ZAPSIGN_SIGNER_EMAIL || "").trim();
  if (!email) return null;
  return {
    email,
    nome: (process.env.ZAPSIGN_SIGNER_NAME || "Grape M\xEDdia LTDA").trim(),
    // Só com o user_token a Grape assina SOZINHA, pela API — e isso depende do
    // add-on de assinatura em lote. Sem ele, o segundo signatário existe do
    // mesmo jeito e assina abrindo o próprio link, que é recurso comum da
    // plataforma e não custa nada a mais.
    userToken: (process.env.ZAPSIGN_USER_TOKEN || "").trim() || null
  };
};
function emailDoToken3(req) {
  const e = req.user?.email;
  return typeof e === "string" && e.includes("@") ? e.toLowerCase().trim() : null;
}
async function zapsign(caminho, init = {}) {
  const chave = (process.env.ZAPSIGN_API_TOKEN || "").trim();
  if (!chave) throw new Error("ZAPSIGN_API_TOKEN n\xE3o configurada no servidor.");
  const r = await fetch(`${ZAPSIGN_BASE}${caminho}`, {
    ...init,
    headers: {
      Authorization: `Bearer ${chave}`,
      "Content-Type": "application/json",
      ...init.headers || {}
    }
  });
  const txt = await r.text();
  let json = {};
  try {
    json = txt ? JSON.parse(txt) : {};
  } catch {
    json = { raw: txt };
  }
  if (!r.ok) {
    const detalhe = json?.detail || (json && typeof json === "object" ? Object.entries(json).map(([k, v]) => `${k}: ${Array.isArray(v) ? v.join(", ") : v}`).join(" \xB7 ") : "");
    throw new Error(`ZapSign ${r.status}${detalhe ? `: ${detalhe}` : ""}`.slice(0, 500));
  }
  return json;
}
function telefoneBR(bruto) {
  let n = String(bruto || "").replace(/\D/g, "");
  if (n.startsWith("55") && n.length > 11) n = n.slice(2);
  n = n.replace(/^0+/, "");
  if (n.length < 10 || n.length > 11) return null;
  return { pais: "55", numero: n };
}
async function migrateZapsign(pool) {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS zapsign_documentos (
      id           serial PRIMARY KEY,
      lead_id      text,                   -- crm_comercial_leads.id \xE9 TEXT (uuid), n\xE3o int
      doc_token    text NOT NULL UNIQUE,   -- token do documento no ZapSign
      open_id      integer,
      signer_token text,                   -- token do signat\xE1rio (comp\xF5e o sign_url)
      grape_signer_token text,             -- 2\xBA signat\xE1rio: a Grape, que assina pela API
      grape_signed_at    timestamptz,
      nome         text NOT NULL,
      signatario   text,
      telefone     text,
      sign_url     text,
      status       text NOT NULL DEFAULT 'pending',
      signed_file  text,
      valor        numeric(12,2),
      documento    text,                   -- CNPJ/CPF gravado no contrato
      created_by   text,
      created_at   timestamptz NOT NULL DEFAULT now(),
      updated_at   timestamptz NOT NULL DEFAULT now(),
      signed_at    timestamptz
    );
    CREATE INDEX IF NOT EXISTS idx_zapsign_lead ON zapsign_documentos (lead_id, created_at DESC);
    ALTER TABLE zapsign_documentos ADD COLUMN IF NOT EXISTS grape_signer_token text;
    ALTER TABLE zapsign_documentos ADD COLUMN IF NOT EXISTS grape_sign_url text;
    ALTER TABLE zapsign_documentos ADD COLUMN IF NOT EXISTS grape_signed_at timestamptz;
  `);
  await pool.query(`
    ALTER TABLE zapsign_documentos ALTER COLUMN lead_id TYPE text USING lead_id::text;
  `).catch((e) => console.warn("[zapsign] lead_id j\xE1 era texto?", e.message));
}
