  const LEGACY_CRITERIA = [
    { key: "nota_campanhas", criterio_id: -1, label: "Campanhas", icon: "Megaphone", cor: "violet" },
    { key: "nota_grapehub", criterio_id: -2, label: "GrapeHub", icon: "LayoutGrid", cor: "emerald" },
    { key: "nota_reunioes", criterio_id: -3, label: "Reuni\xF5es Internas", icon: "Users", cor: "blue" },
    { key: "nota_tmr", criterio_id: -4, label: "TMR / Grupos", icon: "MessageCircle", cor: "amber" }
  ];
  const buildNotas = (row) => {
    if (Array.isArray(row.notas) && row.notas.length) return row.notas;
    const arr = [];
    for (const l of LEGACY_CRITERIA) {
      if (row[l.key] != null) {
        arr.push({ criterio_id: l.criterio_id, label: l.label, icon: l.icon, cor: l.cor, nota: Number(row[l.key]) });
      }
    }
    return arr;
  };
  app.get("/api/colaboradores/:id/desempenho", async (req, res) => {
    try {
      const { rows } = await pool.query(`
        SELECT c.*, av.name AS avaliador_nome
        FROM collaborator_performance_cycles c
        LEFT JOIN collaborators av ON av.id = c.avaliador_id
        WHERE c.collaborator_id = $1
        ORDER BY c.periodo_inicio DESC
      `, [req.params.id]);
      const { rows: critRows } = await pool.query(
        `SELECT id, label, descricao, icon, cor FROM performance_criteria`
      );
      const critAtual = new Map(critRows.map((c) => [Number(c.id), c]));
      const result = rows.map((r) => {
        const notas = buildNotas(r).map((n) => {
          const atual = critAtual.get(Number(n.criterio_id));
          return atual ? { ...n, label: atual.label, descricao: atual.descricao, icon: atual.icon, cor: atual.cor } : n;
        });
        const media = notas.length ? Math.round(notas.reduce((a, n) => a + Number(n.nota), 0) / notas.length * 100) / 100 : 0;
        return { ...r, notas, media_geral: media };
      });
      res.json(result);
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });
  app.get("/api/colaboradores/:id/desempenho/resumo", async (req, res) => {
    try {
      const { rows: all } = await pool.query(`
        SELECT
          nota_campanhas, nota_grapehub, nota_reunioes, nota_tmr,
          ROUND((nota_campanhas + nota_grapehub + nota_reunioes + nota_tmr) / 4.0, 2) AS media_geral
        FROM collaborator_performance_cycles
        WHERE collaborator_id = $1
        ORDER BY periodo_inicio DESC
      `, [req.params.id]);
      if (all.length === 0) return res.json(null);
      const avg = (field) => {
        const sum = all.reduce((a, r) => a + Number(r[field]), 0);
        return parseFloat((sum / all.length).toFixed(2));
      };
      const trend = (field) => {
        if (all.length < 2) return { t: "estavel", d: 0 };
        const last = Number(all[0][field]);
        const prev = Number(all[1][field]);
        const diff = parseFloat((last - prev).toFixed(2));
        return { t: diff > 0 ? "subiu" : diff < 0 ? "caiu" : "estavel", d: Math.abs(diff) };
      };
      const tc = trend("nota_campanhas");
      const tg = trend("nota_grapehub");
      const tr = trend("nota_reunioes");
      const tt = trend("nota_tmr");
      res.json({
        media_campanhas: avg("nota_campanhas"),
        media_grapehub: avg("nota_grapehub"),
        media_reunioes: avg("nota_reunioes"),
        media_tmr: avg("nota_tmr"),
        media_geral: avg("media_geral"),
        tendencia_campanhas: tc.t,
        diff_campanhas: tc.d,
        tendencia_grapehub: tg.t,
        diff_grapehub: tg.d,
        tendencia_reunioes: tr.t,
        diff_reunioes: tr.d,
        tendencia_tmr: tt.t,
        diff_tmr: tt.d
      });
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });
